const jobId = String($json.job_id ?? '')
  .trim()
  .toLowerCase();

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

if (!uuidPattern.test(jobId)) {
  throw new Error('job_id must be a valid UUID');
}

return [{ json: { job_id: jobId } }];

const job = $input.first().json;

if (!job.job_exists) {
  throw new Error(`Job ${job.requested_job_id} was not found`);
}

const normalVisualState =
  job.status === 'processing' &&
  ['voiceover', 'visuals'].includes(job.current_stage);

const retryVisualState =
  job.status === 'failed' &&
  job.current_stage === 'visuals';

if (!normalVisualState && !retryVisualState) {
  throw new Error(
    `Job ${job.job_id} is not eligible for visual sourcing: ` +
    `status=${job.status}, current_stage=${job.current_stage}`
  );
}

const requiredScenesByDuration = {
  15: 4,
  30: 8,
  45: 12,
  60: 15,
};

const requiredSceneCount =
  requiredScenesByDuration[Number(job.target_duration_seconds)];

if (!requiredSceneCount) {
  throw new Error(
    `Unsupported target_duration_seconds: ${job.target_duration_seconds}`
  );
}

if (!Array.isArray(job.scenes)) {
  throw new Error(`Job ${job.job_id} scenes are unavailable`);
}

if (
  Number(job.scene_count) !== requiredSceneCount ||
  job.scenes.length !== requiredSceneCount
) {
  throw new Error(
    `Job ${job.job_id} must have exactly ${requiredSceneCount} scenes`
  );
}

const seenQueries = new Set();
let pendingSceneCount = 0;
let completedSceneCount = 0;

for (let index = 0; index < job.scenes.length; index++) {
  const scene = job.scenes[index];
  const expected = index + 1;

  if (Number(scene.scene_number) !== expected) {
    throw new Error(
      `Invalid scene_number at position ${expected}: received ${scene.scene_number}`
    );
  }

  for (const field of [
    'scene_id',
    'narration',
    'visual_description',
    'visual_query',
  ]) {
    if (
      typeof scene[field] !== 'string' ||
      scene[field].trim() === ''
    ) {
      throw new Error(
        `Scene ${expected} is missing ${field}`
      );
    }
  }

  const query = scene.visual_query.trim();

  if (query.length > 100) {
    throw new Error(
      `Scene ${expected} visual_query exceeds 100 characters`
    );
  }

  const queryKey = query.toLowerCase();
  if (seenQueries.has(queryKey)) {
    throw new Error(
      `Duplicate visual_query at scene ${expected}`
    );
  }
  seenQueries.add(queryKey);

  if (!['factual', 'generic'].includes(scene.visual_subject_type)) {
    throw new Error(
      `Scene ${expected} has invalid visual_subject_type`
    );
  }

  const audioPath =
    typeof scene.audio_path === 'string'
      ? scene.audio_path.trim()
      : '';
  const duration = Number(scene.duration_seconds);

  if (
    !audioPath ||
    !Number.isFinite(duration) ||
    duration <= 0
  ) {
    throw new Error(
      `Scene ${expected} does not have completed voiceover`
    );
  }

  const visualPath =
    typeof scene.visual_path === 'string'
      ? scene.visual_path.trim()
      : '';
  const assetCount = Number(scene.asset_count ?? 0);

  if (!Number.isInteger(assetCount) || assetCount < 0) {
    throw new Error(
      `Scene ${expected} has invalid asset_count`
    );
  }

  if (visualPath) {
    if (assetCount < 1) {
      throw new Error(
        `Scene ${expected} has visual_path without asset metadata`
      );
    }
    completedSceneCount++;
  } else {
    if (assetCount !== 0) {
      throw new Error(
        `Scene ${expected} has asset metadata without visual_path`
      );
    }
    pendingSceneCount++;
  }
}

if (
  job.current_stage === 'voiceover' &&
  completedSceneCount > 0
) {
  throw new Error(
    `Job ${job.job_id} has visual output before visual stage start`
  );
}

const alreadyComplete =
  pendingSceneCount === 0 &&
  completedSceneCount === requiredSceneCount;

if (
  alreadyComplete &&
  job.current_stage !== 'visuals'
) {
  throw new Error(
    `Job ${job.job_id} is visually complete but current_stage is ${job.current_stage}`
  );
}

return [{
  json: {
    ...job,
    required_scene_count: requiredSceneCount,
    pending_scene_count: pendingSceneCount,
    completed_scene_count: completedSceneCount,
    already_complete: alreadyComplete,
  },
}];

const transition = $input.first().json;
const job = $('Require Eligible Visual Job').first().json;

if (transition.ready_to_run !== true) {
  throw new Error(
    `Job ${job.job_id} could not enter or resume visuals stage`
  );
}

if (String(transition.job_id) !== String(job.job_id)) {
  throw new Error('Visual stage transition job_id mismatch');
}

if (
  transition.status !== 'processing' ||
  transition.current_stage !== 'visuals'
) {
  throw new Error(
    `Unexpected visual state: status=${transition.status}, ` +
    `current_stage=${transition.current_stage}`
  );
}

const pendingScenes = job.scenes.filter((scene) => {
  const visualPath =
    typeof scene.visual_path === 'string'
      ? scene.visual_path.trim()
      : '';
  return !visualPath;
});

if (pendingScenes.length === 0) {
  throw new Error(
    `Job ${job.job_id} has no pending visual scenes`
  );
}

return pendingScenes.map((scene) => ({
  json: {
    job_id: job.job_id,
    scene_id: scene.scene_id,
    scene_number: Number(scene.scene_number),
    narration: scene.narration.trim(),
    visual_description: scene.visual_description.trim(),
    visual_query: scene.visual_query.trim(),
    visual_subject_type: scene.visual_subject_type,
  },
}));

function textTokens(value) {
  const stop = new Set([
    'the','and','for','with','from','into','over','under','about',
    'this','that','these','those','their','there','where','when',
    'what','which','who','why','how','its','his','her','our','your',
    'image','photo','picture','view','scene'
  ]);

  return String(value ?? '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .split(/\s+/u)
    .filter((token) => token.length >= 3 && !stop.has(token));
}

function overlapScore(query, candidateText) {
  const q = new Set(textTokens(query));
  const c = new Set(textTokens(candidateText));
  let score = 0;
  for (const token of q) {
    if (c.has(token)) score += 10;
  }
  return score;
}

function cleanText(value) {
  return String(value ?? '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 1000);
}

const response = $json;
const scene = $('Prepare Visual Items').item.json;
const pages = Array.isArray(response?.query?.pages)
  ? response.query.pages
  : [];

const supported = new Set([
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/gif',
]);
const maxBytes = 24 * 1024 * 1024;

const candidates = [];

for (let index = 0; index < pages.length; index++) {
  const page = pages[index];
  const info = page?.imageinfo?.[0] ?? {};
  const mime = String(info.mime ?? '').toLowerCase();
  const url = String(info.url ?? '').trim();
  const width = Number(info.width);
  const height = Number(info.height);
  const size = Number(info.size ?? 0);

  if (
    !supported.has(mime) ||
    !url ||
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    width < 320 ||
    height < 320 ||
    (Number.isFinite(size) && size > maxBytes)
  ) {
    continue;
  }

  const ext = info.extmetadata ?? {};
  const title = String(page.title ?? '');
  const overlap =
    overlapScore(scene.visual_query, title);
  const score =
    overlap +
    Math.max(0, 10 - index);

  candidates.push({
    index,
    overlap,
    score,
    title,
    info,
    ext,
    width,
    height,
    size,
  });
}

candidates.sort((a, b) =>
  b.score - a.score || a.index - b.index
);

const selected = candidates[0];

if (!selected || selected.overlap < 10) {
  return {
    json: {
      ...scene,
      candidate_found: false,
      fallback_reason: 'No acceptable Wikimedia Commons candidate matched the visual query',
    },
  };
}

const license =
  cleanText(selected.ext?.LicenseShortName?.value);
const licenseUrl =
  cleanText(selected.ext?.LicenseUrl?.value);
const author =
  cleanText(
    selected.ext?.Artist?.value ||
    selected.ext?.Credit?.value
  );
const sourceUrl =
  String(selected.info.descriptionurl ?? '').trim() ||
  `https://commons.wikimedia.org/wiki/${encodeURIComponent(
    selected.title.replace(/\s+/g, '_')
  )}`;

return {
  json: {
    ...scene,
    candidate_found: true,
    provider: 'wikimedia',
    provider_asset_id: String(selected.title),
    download_url: String(selected.info.url),
    source_url: sourceUrl,
    author: author || null,
    license: license || null,
    license_url: licenseUrl || null,
    metadata: {
      selected_rank: selected.index + 1,
      selection_score: selected.score,
      token_overlap_score: selected.overlap,
      source_title: selected.title,
      source_mime: String(selected.info.mime ?? ''),
      source_width: selected.width,
      source_height: selected.height,
      source_bytes: Number.isFinite(selected.size)
        ? selected.size
        : null,
    },
  },
};

function textTokens(value) {
  const stop = new Set([
    'the','and','for','with','from','into','over','under','about',
    'this','that','these','those','their','there','where','when',
    'what','which','who','why','how','its','his','her','our','your',
    'image','photo','picture','view','scene'
  ]);

  return String(value ?? '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .split(/\s+/u)
    .filter((token) => token.length >= 3 && !stop.has(token));
}

function overlapScore(query, candidateText) {
  const queryTokens = [...new Set(textTokens(query))];
  const candidateTokens = new Set(textTokens(candidateText));

  let score = 0;
  const matchedTokens = [];

  for (let index = 0; index < queryTokens.length; index++) {
    const token = queryTokens[index];
    if (!candidateTokens.has(token)) continue;

    const tokenWeight = Math.max(10, 30 - index * 5);
    score += tokenWeight;
    matchedTokens.push(token);
  }

  return {
    score,
    matchedTokens,
    queryTokens,
    queryTokenCount: queryTokens.length,
    primaryToken: queryTokens[0] ?? null,
  };
}

function pixabaySubjectText(pageUrl) {
  const raw = String(pageUrl ?? '').trim();
  if (!raw) return '';

  const path = raw.split('?')[0].replace(/\/+$/g, '');
  const slug = path.split('/').pop() ?? '';

  return slug
    .replace(/-\d+$/g, '')
    .replace(/-/g, ' ');
}

const response = $json;
const scene = $('Prepare Visual Items').item.json;
const hits = Array.isArray(response?.hits)
  ? response.hits
  : [];
const maxBytes = 24 * 1024 * 1024;

const candidates = [];

for (let index = 0; index < hits.length; index++) {
  const hit = hits[index] ?? {};
  const url =
    String(hit.largeImageURL ?? hit.webformatURL ?? '').trim();
  const width = Number(hit.imageWidth ?? 0);
  const height = Number(hit.imageHeight ?? 0);
  const size = Number(hit.imageSize ?? 0);

  if (
    !url ||
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    width < 320 ||
    height < 320 ||
    (Number.isFinite(size) && size > maxBytes)
  ) {
    continue;
  }

  const text = `${hit.tags ?? ''}`;
  const overlapResult =
    overlapScore(scene.visual_query, text);
  const overlap = overlapResult.score;
  const coreTokens = overlapResult.queryTokens.slice(0, 2);
  const subjectTokens = new Set(
    textTokens(pixabaySubjectText(hit.pageURL))
  );
  const subjectMatchedTokens = coreTokens.filter((token) =>
    subjectTokens.has(token)
  );
  const score =
    overlap +
    Math.max(0, 10 - index) +
    (height >= width ? 3 : 0);

  candidates.push({
    index,
    overlap,
    matchedTokens: overlapResult.matchedTokens,
    queryTokens: overlapResult.queryTokens,
    queryTokenCount: overlapResult.queryTokenCount,
    primaryToken: overlapResult.primaryToken,
    coreTokens,
    subjectMatchedTokens,
    score,
    hit,
    url,
    width,
    height,
    size,
  });
}

const queryTokenCount = candidates[0]?.queryTokenCount ?? 0;
const requiredMatchCount = Math.min(2, Math.max(1, queryTokenCount));
const primaryToken = candidates[0]?.primaryToken ?? null;
const requiredCoreTokens = candidates[0]?.coreTokens ?? [];

const acceptableCandidates = candidates.filter((candidate) =>
  candidate.overlap >= 10 &&
  candidate.matchedTokens.length >= requiredMatchCount &&
  (!primaryToken || candidate.matchedTokens.includes(primaryToken)) &&
  candidate.subjectMatchedTokens.length === requiredCoreTokens.length
);

acceptableCandidates.sort((a, b) =>
  b.score - a.score || a.index - b.index
);

const selected = acceptableCandidates[0];

if (!selected) {
  return {
    json: {
      ...scene,
      candidate_found: false,
      fallback_reason: 'No acceptable Pixabay candidate met core visual-query subject coverage',
    },
  };
}

return {
  json: {
    ...scene,
    candidate_found: true,
    provider: 'pixabay',
    provider_asset_id: String(selected.hit.id ?? ''),
    download_url: selected.url,
    source_url: String(selected.hit.pageURL ?? '').trim() || null,
    author: String(selected.hit.user ?? '').trim() || null,
    license: 'Pixabay Content License',
    license_url: 'https://pixabay.com/service/license-summary/',
    metadata: {
      selected_rank: selected.index + 1,
      selection_score: selected.score,
      token_overlap_score: selected.overlap,
      matched_tokens: selected.matchedTokens,
      required_match_count: requiredMatchCount,
      required_primary_token: primaryToken,
      required_core_tokens: requiredCoreTokens,
      subject_matched_tokens: selected.subjectMatchedTokens,
      tags: String(selected.hit.tags ?? ''),
      source_width: selected.width,
      source_height: selected.height,
      source_bytes: Number.isFinite(selected.size)
        ? selected.size
        : null,
    },
  },
};

const scene = $('Prepare Visual Items').item.json;
const errorItem = $json ?? {};

let reason =
  errorItem.error?.message ||
  errorItem.error?.description ||
  errorItem.errorMessage ||
  errorItem.message ||
  'Pixabay search failed';

return {
  json: {
    ...scene,
    fallback_reason: String(reason).slice(0, 1000),
  },
};

function textTokens(value) {
  const stop = new Set([
    'the','and','for','with','from','into','over','under','about',
    'this','that','these','those','their','there','where','when',
    'what','which','who','why','how','its','his','her','our','your',
    'image','photo','picture','view','scene'
  ]);

  return String(value ?? '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .split(/\s+/u)
    .filter((token) => token.length >= 3 && !stop.has(token));
}

function overlapScore(query, candidateText) {
  const queryTokens = [...new Set(textTokens(query))];
  const candidateTokens = new Set(textTokens(candidateText));

  let score = 0;
  const matchedTokens = [];

  for (let index = 0; index < queryTokens.length; index++) {
    const token = queryTokens[index];
    if (!candidateTokens.has(token)) continue;

    const tokenWeight = Math.max(10, 30 - index * 5);
    score += tokenWeight;
    matchedTokens.push(token);
  }

  return {
    score,
    matchedTokens,
    queryTokens,
    queryTokenCount: queryTokens.length,
    primaryToken: queryTokens[0] ?? null,
  };
}

const response = $json;
const scene = $('Prepare Visual Items').item.json;
const photos = Array.isArray(response?.photos)
  ? response.photos
  : [];

const candidates = [];

for (let index = 0; index < photos.length; index++) {
  const photo = photos[index] ?? {};
  const url = String(photo?.src?.original ?? '').trim();
  const width = Number(photo.width ?? 0);
  const height = Number(photo.height ?? 0);

  if (
    !url ||
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    width < 320 ||
    height < 320
  ) {
    continue;
  }

  const alt = String(photo.alt ?? '');
  const overlapResult =
    overlapScore(scene.visual_query, alt);
  const overlap = overlapResult.score;
  const coreTokens = overlapResult.queryTokens.slice(0, 2);
  const subjectTokens = new Set(textTokens(alt));
  const subjectMatchedTokens = coreTokens.filter((token) =>
    subjectTokens.has(token)
  );
  const score =
    overlap +
    Math.max(0, 10 - index) +
    (height >= width ? 3 : 0);

  candidates.push({
    index,
    overlap,
    matchedTokens: overlapResult.matchedTokens,
    queryTokens: overlapResult.queryTokens,
    queryTokenCount: overlapResult.queryTokenCount,
    primaryToken: overlapResult.primaryToken,
    coreTokens,
    subjectMatchedTokens,
    score,
    photo,
    url,
    width,
    height,
  });
}

const queryTokenCount = candidates[0]?.queryTokenCount ?? 0;
const requiredMatchCount = Math.min(2, Math.max(1, queryTokenCount));
const primaryToken = candidates[0]?.primaryToken ?? null;
const requiredCoreTokens = candidates[0]?.coreTokens ?? [];

const acceptableCandidates = candidates.filter((candidate) =>
  candidate.overlap >= 10 &&
  candidate.matchedTokens.length >= requiredMatchCount &&
  (!primaryToken || candidate.matchedTokens.includes(primaryToken)) &&
  candidate.subjectMatchedTokens.length === requiredCoreTokens.length
);

acceptableCandidates.sort((a, b) =>
  b.score - a.score || a.index - b.index
);

const selected = acceptableCandidates[0];

if (!selected) {
  return {
    json: {
      ...scene,
      candidate_found: false,
      fallback_reason: 'No acceptable Pexels candidate met core visual-query subject coverage',
    },
  };
}

return {
  json: {
    ...scene,
    candidate_found: true,
    provider: 'pexels',
    provider_asset_id: String(selected.photo.id ?? ''),
    download_url: selected.url,
    source_url: String(selected.photo.url ?? '').trim() || null,
    author:
      String(selected.photo.photographer ?? '').trim() || null,
    license: 'Pexels License',
    license_url: 'https://www.pexels.com/license/',
    metadata: {
      selected_rank: selected.index + 1,
      selection_score: selected.score,
      token_overlap_score: selected.overlap,
      matched_tokens: selected.matchedTokens,
      required_match_count: requiredMatchCount,
      required_primary_token: primaryToken,
      required_core_tokens: requiredCoreTokens,
      subject_matched_tokens: selected.subjectMatchedTokens,
      alt: String(selected.photo.alt ?? ''),
      source_width: selected.width,
      source_height: selected.height,
    },
  },
};

const item = $json;

if (
  item.candidate_found !== true ||
  typeof item.download_url !== 'string' ||
  item.download_url.trim() === ''
) {
  throw new Error('Selected visual candidate is incomplete');
}

return { json: item };

const visualPath =
  typeof $json.visual_path === 'string'
    ? $json.visual_path.trim()
    : '';
const width = Number($json.width);
const height = Number($json.height);
const bytes = Number($json.bytes);

if (!visualPath) {
  throw new Error(
    'media-worker response is missing visual_path'
  );
}

if (
  !Number.isFinite(width) ||
  width <= 0 ||
  !Number.isFinite(height) ||
  height <= 0
) {
  throw new Error(
    'media-worker returned invalid visual dimensions'
  );
}

if (!Number.isFinite(bytes) || bytes <= 0) {
  throw new Error(
    'media-worker returned invalid visual byte size'
  );
}

return {
  json: {
    ...$json,
    visual_path: visualPath,
    width,
    height,
    bytes,
  },
};

const stored = $json;
const selected = $('Prepare Selected Download').item.json;

return {
  json: {
    job_id: selected.job_id,
    scene_id: selected.scene_id,
    scene_number: selected.scene_number,
    provider: selected.provider,
    provider_asset_id: selected.provider_asset_id || null,
    source_url: selected.source_url || null,
    author: selected.author || null,
    license: selected.license || null,
    license_url: selected.license_url || null,
    visual_path: stored.visual_path,
    metadata: {
      ...(selected.metadata ?? {}),
      normalized_width: Number(stored.width),
      normalized_height: Number(stored.height),
      normalized_codec: stored.codec_name ?? null,
      normalized_bytes: Number(stored.bytes),
      source_content_type: stored.source_content_type ?? null,
      stored_by: 'media-worker',
    },
  },
};

const selected = $('Prepare Selected Download').item.json;
const errorItem = $json ?? {};

const candidates = [
  errorItem.error?.message,
  errorItem.error?.description,
  errorItem.error,
  errorItem.errorMessage,
  errorItem.message,
];

let message = candidates.find(
  (value) =>
    typeof value === 'string' &&
    value.trim() !== ''
);

if (!message) {
  try {
    message = JSON.stringify(errorItem);
  } catch {
    message = 'External visual download/store failed';
  }
}

return {
  json: {
    ...selected,
    retry_pexels: selected.provider === 'pixabay',
    fallback_reason:
      String(message || 'External visual failed')
        .trim()
        .slice(0, 1000),
  },
};

const scene = $('Prepare Visual Items').item.json;
const incoming = $json ?? {};

const candidates = [
  incoming.fallback_reason,
  incoming.error?.message,
  incoming.error?.description,
  incoming.error,
  incoming.errorMessage,
  incoming.message,
];

let reason = candidates.find(
  (value) =>
    typeof value === 'string' &&
    value.trim() !== ''
);

if (!reason) {
  reason = 'No acceptable external visual asset was available';
}

return {
  json: {
    ...scene,
    fallback_reason:
      String(reason).trim().slice(0, 1000),
  },
};

const visualPath =
  typeof $json.visual_path === 'string'
    ? $json.visual_path.trim()
    : '';
const width = Number($json.width);
const height = Number($json.height);
const bytes = Number($json.bytes);

if ($json.fallback !== true || !visualPath) {
  throw new Error(
    'media-worker fallback response is invalid'
  );
}

if (
  !Number.isFinite(width) ||
  width <= 0 ||
  !Number.isFinite(height) ||
  height <= 0 ||
  !Number.isFinite(bytes) ||
  bytes <= 0
) {
  throw new Error(
    'media-worker fallback dimensions/bytes are invalid'
  );
}

return {
  json: {
    ...$json,
    visual_path: visualPath,
    width,
    height,
    bytes,
  },
};

const stored = $json;
const scene = $('Prepare Fallback Context').item.json;

return {
  json: {
    job_id: scene.job_id,
    scene_id: scene.scene_id,
    scene_number: scene.scene_number,
    provider: 'local_fallback',
    provider_asset_id: null,
    source_url: null,
    author: null,
    license: null,
    license_url: null,
    visual_path: stored.visual_path,
    metadata: {
      fallback: true,
      reason: scene.fallback_reason,
      normalized_width: Number(stored.width),
      normalized_height: Number(stored.height),
      normalized_codec: stored.codec_name ?? null,
      normalized_bytes: Number(stored.bytes),
      stored_by: 'media-worker',
    },
  },
};

const result = $json;

if (!result.job_exists) {
  throw new Error(
    `Job ${result.job_id} was not found during visual completion check`
  );
}

if (
  result.status !== 'processing' ||
  result.current_stage !== 'visuals'
) {
  throw new Error(
    `Unexpected job state after visuals: ` +
    `status=${result.status}, current_stage=${result.current_stage}`
  );
}

if (result.all_visuals_ready !== true) {
  throw new Error(
    `Visual sourcing is incomplete for job ${result.job_id}: ` +
    `ready=${result.ready_scene_count}, ` +
    `total=${result.total_scene_count}, ` +
    `required=${result.required_scene_count}, ` +
    `incomplete=${result.incomplete_scene_count}`
  );
}

return {
  json: {
    job_id: result.job_id,
    status: result.status,
    current_stage: result.current_stage,
    scene_count: Number(result.total_scene_count),
    visuals_complete: true,
  },
};

const errorItem = $input.first()?.json ?? {};
const job = $('Require Eligible Visual Job').first().json;

if (
  typeof job.job_id !== 'string' ||
  job.job_id.trim() === ''
) {
  throw new Error(
    'Validated job_id is unavailable while recording visual failure'
  );
}

const candidates = [
  errorItem.error?.message,
  errorItem.error?.description,
  errorItem.error,
  errorItem.errorMessage,
  errorItem.errorDescription,
  errorItem.message,
];

let message = candidates.find(
  (value) =>
    typeof value === 'string' &&
    value.trim() !== ''
);

if (!message) {
  try {
    message = JSON.stringify(errorItem);
  } catch {
    message = '';
  }
}

message = String(
  message || 'Unknown visual sourcing stage failure'
)
  .trim()
  .slice(0, 4000);

return [{
  json: {
    job_id: job.job_id,
    last_error: message,
  },
}];
